-- Run in Supabase SQL Editor as postgres. No existing rows are deleted.
SET search_path TO public;
BEGIN;
CREATE TABLE IF NOT EXISTS public.schema_versions (version integer PRIMARY KEY, "appliedAt" varchar(255));
create table if not exists "properties" ("id" varchar(255), "slug" varchar(255), "title" varchar(255), "category" varchar(255), "location" varchar(255), "status" varchar(255), "price" double precision, "areaSqft" double precision, "bedrooms" integer default '0', "bathrooms" integer default '0', "featured" boolean default '0', "archived" boolean default '0', "demo" boolean default '0', "version" integer default '1', "data" text, "createdAt" varchar(255), "updatedAt" varchar(255), constraint "properties_pkey" primary key ("id"));
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='properties_slug_unique' AND conrelid='public.properties'::regclass) THEN ALTER TABLE public."properties" ADD CONSTRAINT "properties_slug_unique" UNIQUE ("slug"); END IF; END $$;
create index if not exists "properties_category_index" on "properties" ("category");
create index if not exists "properties_location_index" on "properties" ("location");
create index if not exists "properties_status_index" on "properties" ("status");
create index if not exists "properties_price_index" on "properties" ("price");
create index if not exists "properties_areasqft_index" on "properties" ("areaSqft");
create index if not exists "properties_createdat_index" on "properties" ("createdAt");
create index if not exists "properties_archived_status_category_index" on "properties" ("archived", "status", "category");
create table if not exists "settings" ("id" integer, "data" text, constraint "settings_pkey" primary key ("id"));
create table if not exists "users" ("id" varchar(255), "email" varchar(255), "hash" varchar(255), "role" varchar(255), "sessionVersion" integer default '1', constraint "users_pkey" primary key ("id"));
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='users_email_unique' AND conrelid='public.users'::regclass) THEN ALTER TABLE public."users" ADD CONSTRAINT "users_email_unique" UNIQUE ("email"); END IF; END $$;
create table if not exists "enquiries" ("id" varchar(255), "name" varchar(255), "phone" varchar(255), "email" varchar(255), "interest" varchar(255), "location" varchar(255), "message" text, "propertyId" varchar(255), "visitDate" varchar(255), "status" varchar(255) default 'New', "notes" text default '', "createdAt" varchar(255), constraint "enquiries_pkey" primary key ("id"));
create index if not exists "enquiries_status_index" on "enquiries" ("status");
create index if not exists "enquiries_createdat_index" on "enquiries" ("createdAt");
create table if not exists "audit" ("id" varchar(255), "userId" varchar(255), "action" varchar(255), "target" varchar(255), "createdAt" varchar(255), constraint "audit_pkey" primary key ("id"));
create table if not exists "limits" ("key" varchar(255), "count" integer, "expires" bigint, constraint "limits_pkey" primary key ("key"));
create table if not exists "resets" ("hash" varchar(255), "userId" varchar(255), "expires" bigint, constraint "resets_pkey" primary key ("hash"));
create table if not exists "events" ("id" varchar(255), "kind" varchar(255), "propertyId" varchar(255), "day" varchar(255), constraint "events_pkey" primary key ("id"));
create index if not exists "events_kind_index" on "events" ("kind");
create index if not exists "events_day_index" on "events" ("day");
INSERT INTO public.settings (id,data) VALUES (1,'{"name":"SS Regalis Reality","tagline":"Building Trust, Creating Value.","description":"Based in Kanchipuram, connecting people with land, homes, and new beginnings across Tamil Nadu.","phone":"","whatsapp":"919080164771","email":"ssregaladvisory@gmail.com","address":"","hours":"","mapsUrl":"","instagram":"","facebook":"","twitter":"","youtube":"","logo":"/logo-hd.png","seoTitle":"SS Regalis Reality | Properties across Tamil Nadu","seoDescription":"Explore residential plots, homes, villas and farmland across Tamil Nadu with SS Regalis Reality, based in Kanchipuram.","whatsappMessage":"Hi {business}, I would like to know more about your available properties.","about":"A place to put down roots. A space to build your future. Based in Kanchipuram, SS Regalis Reality brings a considered, personal approach to finding property across Tamil Nadu. Tell us what matters to you, and let’s explore the possibilities together.","showSold":true,"templeModel":""}') ON CONFLICT (id) DO NOTHING;
ALTER TABLE public.schema_versions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.schema_versions FROM anon, authenticated;
ALTER TABLE public.properties ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.properties FROM anon, authenticated;
ALTER TABLE public.settings ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.settings FROM anon, authenticated;
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.users FROM anon, authenticated;
ALTER TABLE public.enquiries ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.enquiries FROM anon, authenticated;
ALTER TABLE public.audit ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.audit FROM anon, authenticated;
ALTER TABLE public.limits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.limits FROM anon, authenticated;
ALTER TABLE public.resets ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.resets FROM anon, authenticated;
ALTER TABLE public.events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.events FROM anon, authenticated;
INSERT INTO public.schema_versions (version,"appliedAt") VALUES (1, CURRENT_TIMESTAMP::text) ON CONFLICT (version) DO NOTHING;
COMMIT;
SELECT tablename, rowsecurity FROM pg_tables WHERE schemaname='public' AND tablename IN ('schema_versions','properties','settings','users','enquiries','audit','limits','resets','events') ORDER BY tablename;
